-- Seed: African-first reference food database (per 100 g values).
-- Generated from app/assets/data/foods.json — keep the two in sync.

on conflict (id) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  region = excluded.region,
  category = excluded.category,
  nutrition_per100g = excluded.nutrition_per100g,
  typical_serving_g = excluded.typical_serving_g,
  serving_label = excluded.serving_label;
